#include <boost/algorithm/string/split.hpp>
#include <boost/regex.hpp>

std::string markdownToHtml(const std::string& markdown) {
    // Replace markdown headers with HTML headers
    markdown = boost::replace_all_copy(markdown, "# ", "<h1>");
    markdown = boost::replace_all_copy(markdown, "## ", "<h2>");
    markdown = boost::replace_all_copy(markdown, "### ", "<h3>");
    markdown = boost::replace_all_copy(markdown, "#### ", "<h4>");
