    // Replace markdown bold text with HTML bold text
    markdown = boost::replace_all_copy(markdown, "**", "<b>");
    markdown = boost::replace_all_copy(markdown, "**", "</b>");

    // Replace markdown italic text with HTML italic text
    markdown = boost::replace_all_copy(markdown, "*", "<i>");
    markdown = boost::replace_all_copy(markdown, "*", "</i>");

    // Replace markdown links with HTML links
    boost::regex linkRegex("([\\w]+)\\(([^)]+)\\)");
    boost::smatch match;
    while (boost::regex_search(markdown, match, linkRegex)) {
